#!/usr/bin/env python3
"""Builds src/study/builtin_content.h from study/lessons and study/scenarios.

Run from mitamaos/firmware:  python3 tools/mkstudy.py
With --check it only reports whether the header is up to date (CI uses it).
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUT = ROOT / "src" / "study" / "builtin_content.h"


def build():
    parts = [
        "// Generated by tools/mkstudy.py from study/ - do not edit by hand.",
        "#pragma once",
        "",
        "namespace study {",
        "",
        "struct BuiltinFile { const char* name; const char* source; };",
        "",
    ]
    for kind in ("lessons", "scenarios"):
        files = sorted((ROOT / "study" / kind).glob("*.lua"))
        parts.append(f"static const BuiltinFile kBuiltin_{kind}[] = {{")
        for f in files:
            text = f.read_text(encoding="utf-8")
            if ")LUA\"" in text:
                sys.exit(f"{f.name}: contains the raw-string delimiter )LUA\"")
            parts.append(f'  {{ "{f.name}", R"LUA({text})LUA" }},')
        parts.append("};")
        parts.append(f"static constexpr int kBuiltin_{kind}_count = {len(files)};")
        parts.append("")
    parts.append("}  // namespace study")
    return "\n".join(parts) + "\n"


def main():
    text = build()
    if "--check" in sys.argv:
        if not OUT.exists() or OUT.read_text(encoding="utf-8") != text:
            sys.exit("src/study/builtin_content.h is out of date: run python3 tools/mkstudy.py")
        print("builtin_content.h is up to date")
        return
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
